class MenuHelp:
    def __init__(self,ctx,navigation,menus,routes,role,system_owner,main,copy_message):
        self.ctx=ctx;self.navigation=navigation;self.menus=menus;self.routes=routes
        self.role=role;self.system_owner=system_owner;self.main=main;self.copy_message=copy_message
        self.keys={v:k for k,v in COMMAND_BUTTONS.items()}|ALIASES

    def data(self,user,section,key,mode):
        result=f'mh:{self.ctx.shop_id}:{user}:{section}:{key}:{mode}'
        if len(result.encode())>64:raise ValueError('Menu callback is too long')
        return result

    def section_markup(self,message,section,expanded=False):
        reply=(self.menus[section](self.role(message)) if section=='root' else
               self.menus[section](self.role(message),system_owner=self.system_owner(message)))
        kb=InlineKeyboardBuilder();user=message.from_user.id
        for row in reply.keyboard:
            buttons=[]
            for item in row:
                if item.text in {BACK,HOME}:continue
                key=self.keys.get(item.text)
                if key is None:raise ValueError(f'Menu item has no help: {item.text}')
                buttons.append(types.InlineKeyboardButton(text=item.text,callback_data=self.data(user,section,key,'show')))
            if buttons:kb.row(*buttons)
        kb.row(types.InlineKeyboardButton(text='Свернуть' if expanded else 'Подробнее',
            callback_data=self.data(user,section,'section','less' if expanded else 'more')))
        if section!='root':kb.row(types.InlineKeyboardButton(text='🏠 Главное меню',callback_data=self.data(user,section,'section','home')))
        return kb.as_markup()

    def visible_keys(self,message,section):
        reply=(self.menus[section](self.role(message)) if section=='root' else
               self.menus[section](self.role(message),system_owner=self.system_owner(message)))
        return {self.keys.get(item.text) for row in reply.keyboard for item in row}

    def section_text(self,section,expanded=False):
        title,brief,details=SECTIONS[section]
        if section=='root':
            shop=self.ctx.repository.get_shop(self.ctx.shop_id)
            if shop:title+=' · '+shop.name
        return f'<b>{escape(title)}</b>\n{escape(brief)}'+('\n\n'+escape(details) if expanded else '')

    async def show_section(self,message,section):
        await self.navigation.show(message,self.section_text(section),parse_mode='HTML',reply_markup=self.section_markup(message,section))

    async def show_root(self,message,title):
        await self.navigation.show(message,title,parse_mode='HTML',reply_markup=self.section_markup(message,'root'))

    def function_text(self,key,expanded=False):
        title=COMMAND_BUTTONS.get(key) or next((label for label,value in ALIASES.items() if value==key),key)
        brief,details=HELP[key]
        return f'<b>{escape(title)}</b>\n{escape(brief)}'+('\n\n'+escape(details) if expanded else '')

    def function_markup(self,user,section,key,expanded=False):
        kb=InlineKeyboardBuilder()
        kb.button(text='▶️ Открыть',callback_data=self.data(user,section,key,'run'))
        kb.button(text='Свернуть' if expanded else 'Подробнее',callback_data=self.data(user,section,key,'less' if expanded else 'more'))
        kb.button(text='⬅️ К разделу',callback_data=self.data(user,section,'section','show'))
        kb.button(text='🏠 Главное меню',callback_data=self.data(user,section,key,'home'))
        kb.adjust(2,2);return kb.as_markup()

    async def handle(self,callback,state):
        if not isinstance(callback.message,types.Message):return await callback.answer('Сообщение недоступно.')
        parts=(callback.data or '').split(':')
        if len(parts)!=6:return await callback.answer('Некорректная кнопка.')
        _,shop,user,section,key,mode=parts
        if str(self.ctx.shop_id)!=shop or str(callback.from_user.id)!=user:
            return await callback.answer('Откройте меню заново для текущего магазина.',show_alert=True)
        if not self.ctx.repository.can_user(callback.from_user.id,self.ctx.shop_id,'view'):
            return await callback.answer('Недостаточно прав.',show_alert=True)
        if section not in self.menus:return await callback.answer('Раздел недоступен.')
        message=self.copy_message(callback.message,key,'',actor_user=callback.from_user)
        if mode=='home':
            await state.clear();await callback.answer();return await self.main(message)
        permission=action_permission(key)
        if not self.ctx.repository.can_user(callback.from_user.id,self.ctx.shop_id,permission):
            return await callback.answer('Функция недоступна для вашей роли.',show_alert=True)
        if (section=='technical' or permission=='technical') and not self.system_owner(message):
            return await callback.answer('Технические функции доступны владельцу всего бота.',show_alert=True)
        if key!='section' and key not in self.visible_keys(message,section):
            return await callback.answer('Функция недоступна для вашей роли в этом разделе.',show_alert=True)
        if key.endswith('_menu') and key.removesuffix('_menu') in self.menus:
            section=key.removesuffix('_menu');key='section'
        if key=='section':
            if mode not in {'show','more','less'}:return await callback.answer('Некорректное действие.')
            await state.clear();await callback.answer()
            expanded=mode=='more'
            try:
                return await callback.message.edit_text(self.section_text(section,expanded),parse_mode='HTML',
                    reply_markup=self.section_markup(message,section,expanded))
            except TelegramBadRequest as exc:
                if 'message is not modified' not in str(exc).lower():raise
                return
        if key not in HELP or key not in self.routes:return await callback.answer('Функция недоступна.')
        if mode=='run':
            handler,needs_state=self.routes[key]
            await callback.answer()
            await state.clear()
            if needs_state:await handler(message,state)
            else:await handler(message)
            # A function may open a new date picker or input prompt. Retire
            # only the help card, never the prompt just created by its handler.
            if message.chat.type=='private' and self.ctx.repository.navigation_message(
                    message.bot.id,message.chat.id,callback.from_user.id)==callback.message.message_id:
                await self.navigation.dismiss(message)
            return
        if mode not in {'show','more','less'}:return await callback.answer('Некорректное действие.')
        if mode=='show':await state.clear()
        await callback.answer()
        try:
            await callback.message.edit_text(self.function_text(key,mode=='more'),parse_mode='HTML',
                reply_markup=self.function_markup(callback.from_user.id,section,key,mode=='more'))
        except TelegramBadRequest as exc:
            if 'message is not modified' not in str(exc).lower():raise
